const invoiceData = {
  meta: {
    invoiceNo: "WM-20260521-0001",
    saleDate: "2026/05/21",
    currency: "VND",
    paymentMethod: "Cash"
  },
  seller: {
    name: "WinMark 2 Hai Bà Trưng",
    address: "2 Bà Trưng - HN",
    phone: "012345678",
    representative: "Đại diện WinMark"
  },
  customer: {
    name: "Nguyễn Văn A",
    age: 20,
    address: "Hà Đông, Hà Nội"
  },
  items: [
    { no: 1, name: "Áo Thun", size: "XL", quantity: 1, price: 200000 },
    { no: 2, name: "Áo Thun", size: "XL", quantity: 1, price: 200000 }
  ],
  promotion: {
    description: "Khuyến mãi 50% dành cho Khách hàng thân thiết",
    discountPercent: 50
  }
};

function formatMoney(value, currency="VND") {
  return new Intl.NumberFormat("vi-VN").format(value) + (currency==="VND" ? " đ" : ` ${currency}`);
}

function formatDate(dateStr) {
  const d = new Date(dateStr);
  return `${d.getDate()}/${d.getMonth()+1}/${d.getFullYear()}`;
}

function createElement(tag, text=null, className=null){
  const el=document.createElement(tag);
  if(text) el.textContent=text;
  if(className) el.className=className;
  return el;
}

function renderInvoice(data){
  const root=document.getElementById("invoice-root");
  root.innerHTML="";

  // Header
  const header=createElement("div", null, "invoice-header");
  const brand=createElement("div", null, "brand");

  const logoImg=document.createElement("img");
  logoImg.src="data:image/jpeg;base64,";
  logoImg.alt="Logo WinMark";
  logoImg.style.width="60px";
  logoImg.style.height="60px";
  logoImg.style.objectFit="contain";
  brand.appendChild(logoImg);

  const brandName=createElement("h1", data.seller.name);
  brand.appendChild(brandName);
  header.appendChild(brand);

  const meta=createElement("div");
  meta.appendChild(createElement("div","HÓA ĐƠN BÁN LẺ","badge"));
  meta.appendChild(createElement("div", `Mã hóa đơn: ${data.meta.invoiceNo}`));
  meta.appendChild(createElement("div", `Ngày: ${formatDate(data.meta.saleDate)}`));
  meta.appendChild(createElement("div", `Thanh toán: ${data.meta.paymentMethod}`));
  header.appendChild(meta);

  root.appendChild(header);

  // Party grid
  const partyGrid=createElement("div", null, "party-grid");
  const sellerDiv=createElement("div","seller party");
  sellerDiv.appendChild(createElement("h3","Đơn vị bán hàng"));
  sellerDiv.appendChild(createElement("p", `Tên: ${data.seller.name}`));
  sellerDiv.appendChild(createElement("p", `Địa chỉ: ${data.seller.address}`));
  sellerDiv.appendChild(createElement("p", `Điện thoại: ${data.seller.phone}`));
  sellerDiv.appendChild(createElement("p", `Người đại diện: ${data.seller.representative}`));

  const customerDiv=createElement("div","customer party");
  customerDiv.appendChild(createElement("h3","Khách hàng"));

  customerDiv.appendChild(createElement("p", `Tên: ${data.customer.name}`));
  customerDiv.appendChild(createElement("p", `Tuổi: ${data.customer.age}`));
  customerDiv.appendChild(createElement("p", `Địa chỉ: ${data.customer.address}`));

  partyGrid.appendChild(sellerDiv);
  partyGrid.appendChild(customerDiv);
  root.appendChild(partyGrid);

  // Bảng sản phẩm
  const table=createElement("table","items-table");
  const thead=createElement("thead");
  thead.innerHTML=`<tr>
    <th>STT</th><th>Tên sản phẩm</th><th>Size</th><th>SL</th><th>Đơn giá</th><th>Thành tiền</th>
  </tr>`;
  table.appendChild(thead);

  const tbody=createElement("tbody");
  let subtotal=0;
  data.items.forEach(item=>{
    const lineTotal=item.quantity*item.price;
    subtotal+=lineTotal;
    const tr=createElement("tr");
    tr.innerHTML=`<td>${item.no}</td><td>${item.name}</td><td>${item.size}</td><td>${item.quantity}</td><td>${formatMoney(item.price)}</td><td>${formatMoney(lineTotal)}</td>`;
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  root.appendChild(table);

  // Promotion & total
  const discount=Math.round(subtotal*data.promotion.discountPercent/100);
  const total=subtotal-discount;

  const promoDiv=createElement("div", null, "promotion-box");
  promoDiv.innerHTML=`<div class="promotion-icon">✓</div><div><p class="promotion-title">Khuyến mãi</p><p class="promotion-text">${data.promotion.description}</p></div>`;
  root.appendChild(promoDiv);

  const totalsDiv=createElement("div","totals");
  totalsDiv.innerHTML=`<div class="total-row">Cộng tiền hàng: <strong>${formatMoney(subtotal)}</strong></div>
  <div class="total-row discount-row">Khấu trừ giảm giá: <strong>-${formatMoney(discount)}</strong></div>
  <div class="grand-total"><div>Tổng thanh toán:</div><div class="money">${formatMoney(total)}</div></div>`;
  root.appendChild(totalsDiv);
}

document.addEventListener("DOMContentLoaded",()=>renderInvoice(invoiceData));